import json,subprocess,hashlib,sys
S=sys.argv[1]
def show(rev):
    return json.loads(subprocess.run(["git","show",f"{rev}:manifest.json"],capture_output=True,check=True).stdout.decode("utf-8"))
a=show("0638544ce1967ccec58ca7f9208c51ce8eaf4f8d"); b=show("c6afa16315d5a88b5045eeb85d429b8f7fd90b1f")
out=["# manifest.json: base 0638544c -> candidate c6afa163","",
"Generated by manifest_diff.py from `git show <rev>:manifest.json` at both commits. For each added or changed entry, the candidate file's",
"sha256 is recomputed from `git show c6afa163:<path>` (the committed bytes) and compared with the manifest value.",""]
for key in sorted(set(a)|set(b)):
    va,vb=a.get(key),b.get(key)
    if va==vb: continue
    if not isinstance(va,dict) or not isinstance(vb,dict):
        out.append(f"{key}: {va} -> {vb}"); continue
    out.append(f"## {key}: {len(va)} -> {len(vb)} entries")
    for p in sorted(set(va)|set(vb)):
        if va.get(p)==vb.get(p): continue
        actual=hashlib.sha256(subprocess.run(["git","show",f"c6afa16315d5a88b5045eeb85d429b8f7fd90b1f:{p}"],capture_output=True,check=True).stdout).hexdigest() if p in vb else None
        st="added" if p not in va else ("removed" if p not in vb else "changed")
        ok="" if actual is None else (" OK (matches committed bytes)" if actual==vb[p] else f" MISMATCH actual {actual}")
        out.append(f"- {st} {p}: {va.get(p,'-')[:16] if va.get(p) else '-'} -> {vb.get(p,'-')}{ok}")
    out.append("")
txt="\n".join(out)+"\n"
open(S+r"\manifest-diff.md","w",encoding="utf-8",newline="\n").write(txt)
print(txt)
